import os, sys, json, re
sys.path.append('storage/shared')
from progressor_tools.validate_transgen_logs import validate_file
from progressor_tools.novelty_stub import run as run_novelty
from progressor_tools.aggregate_novelty import main as agg_novelty

norm = 'storage/shared/progressor_outputs/all_transgen_logs.normalized.jsonl'
schema = 'storage/shared/progressor_tools/schema_hint_progressor_v1.json'
scores = 'storage/shared/progressor_outputs/novelty_scores.jsonl'
summary= 'storage/shared/progressor_outputs/novelty_summary.json'

# Build type hints (supports list[...] specs)
TYPE_MAP = {"int": int, "float": float, "str": str, "bool": bool}
def _parse_type(spec):
    s = str(spec).strip().lower()
    if s in TYPE_MAP: return TYPE_MAP[s]
    m = re.fullmatch(r"list\[(int|float|str|bool)\]", s)
    if m:
        inner = TYPE_MAP[m.group(1)]
        def list_checker(v):
            if not isinstance(v, list): return False
            if inner in (int, float):
                try:
                    for x in v: inner(x)
                    return True
                except Exception:
                    return False
            return all(isinstance(x, inner) for x in v)
        return list_checker
    return None

if not os.path.exists(norm):
    print("FINAL_PIPELINE: normalized not found:", norm)
else:
    if os.path.exists(schema):
        with open(schema, 'r', encoding='utf-8') as f:
            sh = json.load(f)
        required   = sh.get('required') or []
        th_raw     = sh.get('type_hints') or {}
        type_hints = {k: _parse_type(v) for k, v in th_raw.items()}
    else:
        required, type_hints = [], {}

    vres = validate_file(norm, required=required, type_hints=type_hints)
    vsum = {
      "path": vres["path"], "ok": vres["ok_records"], "total": vres["total_lines"],
      "json_errors": vres["json_errors"], "non_dict": vres["non_dict_records"],
      "missing_required": vres["missing_required"], "type_mismatches": vres["type_mismatches"]
    }
    print("FINAL_VALIDATE_SUMMARY:", json.dumps(vsum))

    clean = (vsum["ok"] == vsum["total"] and vsum["total"] > 0 and
             vsum["json_errors"] == 0 and vsum["non_dict"] == 0 and
             vsum["missing_required"] == 0 and vsum["type_mismatches"] == 0)

    if clean:
        os.makedirs(os.path.dirname(scores), exist_ok=True)
        print("FINAL_PIPELINE: validation clean → writing novelty_scores.jsonl")
        run_novelty(in_path=norm, out_path=scores)
        if os.path.exists(scores):
            print("FINAL_PIPELINE: aggregating novelty to", summary)
            agg_novelty()
        else:
            print("FINAL_PIPELINE: novelty scores not written (unexpected).")
    else:
        print("FINAL_PIPELINE: validation not clean; skipping novelty.")
